    public const string SignId="R5-O01:local-sign",PropertyId="R5-O02:local-property",SignTask="R5-O01-W-NAME",PropertyTask="R5-O02-W-RETURN";
    public const string ReedBoard="R5-SIGN-REED-01",LanternBoard="R5-SIGN-LANTERN-01",SignStore="R5-O01:sign-workshop",Junction="R5-S02:local-street-junction",Crew="ROLE-R5-SIGN-CREW";
    public const string Pot="R5-POT-01",Sketch="R5-SKETCH-01",Keeper="ROLE-R5-PROPERTY-KEEPER",PotClaimant="ROLE-R5-POT-CLAIMANT",SketchOwner="ROLE-R5-SKETCH-OWNER";
    private readonly IAdventureRepository _repository;private readonly ChapterFiveService _chapter;private readonly Dictionary<Guid,CommitPlanCommand> _previews=[];
    public OldCityLifeContract Contract {get;}
    public OldCityLocalLifeService(IAdventureRepository repository,ChapterFiveService chapter,OldCityLifeContract contract)
    {_repository=repository;_chapter=chapter;Contract=contract;Require(contract.Version=="r5-local-life-candidate-1"&&chapter.Package.Materials.Single(m=>m.Id=="R5-O01-R-SIGN").English.Contains("Reed Lane",StringComparison.Ordinal)&&chapter.Package.Materials.Single(m=>m.Id=="R5-O02-R-CLAIM").English.Contains("wrapped family sketch",StringComparison.Ordinal),"旧都原局部问题与当前合同未绑定。");foreach(var section in contract.Sections)Require(chapter.Geometry[section.Scene].Spots.Any(p=>p.Id==section.Spot),"本地原真实站位不存在。");}
    private static void Require(bool v,string text){if(!v)throw new InvalidOperationException(text);}
    private static T? Read<T>(BranchSnapshot s,string id) where T:class=>BranchOperations.Read<T>(s,id);
    private void Allowed(BranchSnapshot s)
    {BranchOperations.Safe(s);Require(!s.Entities.Where(e=>e.Kind=="event").Select(e=>StrictJson.Deserialize<EventSession>(e.Json)).Any(e=>e.State==EventLifecycle.Running),"另一前景事件尚未交接。");Require(!s.Entities.Where(e=>e.Kind=="transport_segment").Select(e=>StrictJson.Deserialize<TransportSegment>(e.Json)).Any(t=>t.CargoInTransit&&!t.Completed),"先交接当前实际货物护送。");Require(!BranchOperations.Receipt(s,"Q-604")&&BranchOperations.Entity(s,"final:preparation") is null,"准备封存或最终起航后本地额外工作暂停。");Require(Read<ChapterFiveState>(s,"chapter5") is{Landing:true} st&&st.ContentVersion==_chapter.Package.Version&&s.Receipts.Any(r=>r.SemanticKey=="R5:landing"),"先从实际航程登记旧都本地登陆，不由地区字符串授予旁修。");}
    private void At(BranchSnapshot s,string spot)
    {var a=Read<ActorState>(s,"actor")??throw new InvalidOperationException("当前角色没有真实现场。");string scene=spot.Split('.')[0];var g=_chapter.Geometry[scene];Require(a.Scene==scene&&a.Position.Distance(g.Spots.Single(p=>p.Id==spot).Stand)<=2.5&&new NavigationGrid(g).CanStand(a.Position,true),"请实际走到本地对应安全站位。");}
    private string Access(string id)=>"material:R5-LOCAL-"+id;
    private bool Acquired(BranchSnapshot s,string id)=>BranchOperations.Entity(s,Access(id))?.Json==StrictJson.Serialize(new{version=Contract.Version,fingerprint=Contract.Fingerprint,id});
    private void Source(BranchSnapshot s,string id)=>Require(Acquired(s,id),"公开原件须实际到场取得，不构造未获授权的私人源。");
    public async ValueTask<OldCityLifeView> ViewAsync(){var s=await _repository.SnapshotAsync();return new(s,Read<LocalSignState>(s,SignId),Read<LocalPropertyState>(s,PropertyId),Contract.Sections.Where(x=>Acquired(s,x.Id)).Select(x=>x.Id).ToImmutableArray());}
    public async ValueTask<SettlementSupportSection> OpenContractAsync(string id){var s=await _repository.SnapshotAsync();Source(s,id);return Contract.Sections.Single(x=>x.Id==id);}
    public async ValueTask<CommandResult> DiscoverAsync(string id)
    {var s=await _repository.SnapshotAsync();Allowed(s);var section=Contract.Sections.Single(x=>x.Id==id);At(s,section.Spot);if(Acquired(s,id))return new(CommitStatus.AlreadyCommitted,null,[]);var original=_chapter.Package.Materials.Single(m=>m.Id==(id=="SC-R5-SIGN"?"R5-O01-R-SIGN":"R5-O02-R-CLAIM"));Require(BranchOperations.Entity(s,"material:"+original.Id)?.Json==StrictJson.Serialize(new ChapterMaterialAccess(original.Id,original.Version,original.TranslationVersion,original.Fingerprint,original.SourceRoot,original.Spot)),"先取得冻结原公开阅读，不把新条款冒称原文。");return await Execute(Plan(s,Access(id)+":acquired","old_city_local_public_contract_acquired",new{version=Contract.Version,fingerprint=Contract.Fingerprint,id,private_family_content_supplied=false},[BranchOperations.Change(s,Access(id),"optional_material_access",new{version=Contract.Version,fingerprint=Contract.Fingerprint,id})]));}
    private string[] Reads(BranchSnapshot s)=>s.Entities.Select(e=>e.Id).Concat(new[]{SignId,PropertyId,Access("SC-R5-SIGN"),Access("SC-R5-LOST"),SignId+":consultation",SignId+":display",SignId+":check",SignId+":meaning",SignId+":result",PropertyId+":scope",PropertyId+":owner-permission",PropertyId+":pot-check",PropertyId+":title-check",PropertyId+":original-tag",PropertyId+":correction",PropertyId+":meaning",PropertyId+":result","final:preparation"}).Distinct().ToArray();
    private static bool LocalItem(StoredItem i)=>i.Id is ReedBoard or LanternBoard or Pot or Sketch;
    private CommitPlanCommand Plan(BranchSnapshot s,string key,string action,object body,ImmutableArray<EntityChange> changes,ImmutableArray<ItemChange> items=default,DraftStamp? draft=null)
    {var claims=(items.IsDefault?ImmutableArray<ItemChange>.Empty:items).ToBuilder();foreach(var i in s.Items.Where(LocalItem))if(!claims.Any(x=>x.Id==i.Id))claims.Add(new(i.Id,i.DefinitionId,i.OwnerKind,i.OwnerId,i.OwnerKind,i.OwnerId,i.Slot));return BranchOperations.Plan(_repository,s,key,action,changes,Reads(s),body,items:claims.ToImmutable(),draft:draft);}
    private async ValueTask<CommandResult> Execute(CommitPlanCommand c)
    {var ses=_repository.Session;if(c.Context.Profile!=ses.Profile||c.Context.Branch!=ses.Branch||c.Context.Load!=ses.Load||c.Context.ReleaseId!=ses.ReleaseId)return new(CommitStatus.Rejected,null,[new("stale_load",SignId,"读取世代已变，请重新核对当前地方工作。")]);if(_repository is not IEventLeaseStore lease)throw new InvalidOperationException("地方派工须原子前景占用。");string owner="old-city-life:"+c.Context.Command.Value;Require(await lease.TryLeasesAsync(ses.Load,owner,["input:foreground"]),"另一前景工作尚未交接。");try{return await _repository.ExecuteAsync(c);}finally{await lease.ReleaseLeasesAsync(ses.Load,owner);}}
    private StoredItem Item(BranchSnapshot s,string serial,string definition,string kind,string owner)
    {var i=s.Items.SingleOrDefault(x=>x.Id==serial);Require(i is not null&&i.DefinitionId==definition&&i.OwnerKind==kind&&i.OwnerId==owner,"同一有限实物、规格或原保管地不符，不能以另一件或复制品代替。");return i!;}
    private LocalSignState Sign(BranchSnapshot s)
    {Source(s,"SC-R5-SIGN");var st=Read<LocalSignState>(s,SignId);Require(st is not null&&st.Fingerprint==Contract.Fingerprint&&st.Decision=="accept"&&!st.Completed,"本次地方路牌邀请未接受、源版本已变或已结算。");return st!;}
    public async ValueTask<CommandResult> DecideSignAsync(string decision)
    {var s=await _repository.SnapshotAsync();Allowed(s);At(s,"R5-O01.keeper");Source(s,"SC-R5-SIGN");Require(decision is "accept" or "defer" or "decline","明确接受、暂缓或拒绝同一块地方牌工作。");var old=Read<LocalSignState>(s,SignId);Require(old is null||old.Fingerprint==Contract.Fingerprint&&!old.Completed&&!old.Installed,"已安装或已接收的同牌不能重置。");var st=old is null?new LocalSignState(Guid.NewGuid(),Contract.Fingerprint,decision):old with{Decision=decision};return await Execute(Plan(s,SignId+":decision:"+Guid.NewGuid(),"old_city_local_sign_invitation_decided",new{decision,instance=st.Instance,source=Contract.Fingerprint,scope="one_local_marker_only"},[BranchOperations.Change(s,SignId,"optional_local_sign",st)]));}
    public async ValueTask<CommandResult> ConsultResidentsAsync(string historic,string current)
    {var s=await _repository.SnapshotAsync();Allowed(s);At(s,"R5-O01.keeper");var st=Sign(s);Require(historic=="ROLE-R5-REED-RESIDENT"&&current=="ROLE-R5-LANTERN-RESIDENT"&&historic!=current,"须保留两不同居民的公开记忆，不把一方改成无记忆。");var body=new{historic,current,historic_name="Reed Lane",current_name="Lantern Turn",source=Contract.Fingerprint,neither_memory_deleted=true};return await Execute(Plan(s,SignId+":consultation:"+Guid.NewGuid(),"old_city_two_local_memories_consulted",body,[BranchOperations.Change(s,SignId,"optional_local_sign",st with{Consulted=true}),BranchOperations.Change(s,SignId+":consultation","local_public_consultation",body)]));}
    public async ValueTask<CommandResult> ChooseSignAsync(string main,string other,string maintainer)
    {var s=await _repository.SnapshotAsync();Allowed(s);At(s,"R5-O01.proposal");var st=Sign(s);Require(st.Consulted&&!st.Installed&&maintainer==Crew&&(main=="Reed Lane"&&other=="Also called Lantern Turn"||main=="Lantern Turn"&&other=="Formerly called Reed Lane"),"明确两种合格的当前名称和另一记忆说明，指定既有维护队；不重命名整座城市。");return await Execute(Plan(s,SignId+":proposal:"+Guid.NewGuid(),"old_city_local_sign_name_selected",new{main,other,maintainer,source=Contract.Fingerprint},[BranchOperations.Change(s,SignId,"optional_local_sign",st with{Main=main,Other=other,Board=main=="Reed Lane"?ReedBoard:LanternBoard,VisibleCheck=null})]));}
    public async ValueTask<CommandResult> InspectSignStockAsync(string[] serials)
    {var s=await _repository.SnapshotAsync();Allowed(s);At(s,"R5-O01.sign");var st=Sign(s);Require(serials.SequenceEqual(new[]{ReedBoard,LanternBoard})&&!st.Installed,"必须核当前两块替代样板，不是两次奖励。");if(st.StockInspected){Item(s,ReedBoard,"R5-LOCAL-SIGN-REED","warehouse",SignStore);Item(s,LanternBoard,"R5-LOCAL-SIGN-LANTERN","warehouse",SignStore);return new(CommitStatus.AlreadyCommitted,null,[]);}Require(!s.Items.Any(i=>i.Id is ReedBoard or LanternBoard),"同名有限样板来源不完整，不能补造。");return await Execute(Plan(s,SignId+":stock","old_city_finite_sign_boards_inspected",new{serials,source=Contract.Fingerprint,one_installation=true},[BranchOperations.Change(s,SignId,"optional_local_sign",st with{StockInspected=true})],[new(ReedBoard,"R5-LOCAL-SIGN-REED","new","","warehouse",SignStore,null),new(LanternBoard,"R5-LOCAL-SIGN-LANTERN","new","","warehouse",SignStore,null)]));}
    public async ValueTask<CommandResult> InstallChosenSignAsync(string serial)
    {var s=await _repository.SnapshotAsync();Allowed(s);At(s,"R5-O01.sign");var st=Sign(s);Require(st.Consulted&&st.StockInspected&&!st.Installed&&serial==st.Board&&!string.IsNullOrWhiteSpace(st.Main),"先明确方案并检查样板，只安装当前选中的同一块。");var item=Item(s,serial,serial==ReedBoard?"R5-LOCAL-SIGN-REED":"R5-LOCAL-SIGN-LANTERN","warehouse",SignStore);var display=new LocalSignDisplay(serial,st.Main,st.Other,Crew,st.Configuration+1,"one_local_street_marker");return await Execute(Plan(s,SignId+":installation","old_city_same_local_sign_installed",display,[BranchOperations.Change(s,SignId,"optional_local_sign",st with{Installed=true,Configuration=st.Configuration+1,VisibleCheck=null}),BranchOperations.Change(s,SignId+":display","local_sign_display",display)],[new(serial,item.DefinitionId,item.OwnerKind,item.OwnerId,"installed",Junction,null)]));}
    public async ValueTask<CommandResult> CheckVisibleSignAsync(string main,string other,long configuration)
    {var s=await _repository.SnapshotAsync();Allowed(s);At(s,"R5-O01.sign");var st=Sign(s);Require(st.Installed&&main==st.Main&&other==st.Other&&configuration==st.Configuration,"当前实物和两行可见字必须对应当前安装配置。");Item(s,st.Board,st.Board==ReedBoard?"R5-LOCAL-SIGN-REED":"R5-LOCAL-SIGN-LANTERN","installed",Junction);var display=new LocalSignDisplay(st.Board,main,other,Crew,configuration,"one_local_street_marker");Require(BranchOperations.Entity(s,SignId+":display")?.Json==StrictJson.Serialize(display),"牌面显示与当前同牌不符。");return await Execute(Plan(s,SignId+":visible:"+Guid.NewGuid(),"old_city_current_visible_sign_checked",display,[BranchOperations.Change(s,SignId,"optional_local_sign",st with{VisibleCheck=configuration}),BranchOperations.Change(s,SignId+":check","local_sign_check",display)]));}
    public async ValueTask<DraftSaved> SaveDraftAsync(string task,long revision,DraftId? draft,string body)
    {Require(task is SignTask or PropertyTask,"未登记的本地稿件。");var ses=_repository.Session;return await _repository.SaveAsync(new(ses.Profile,ses.Branch,ses.Load,task,draft,revision,body,Contract.Version));}
    public async ValueTask<CommandResult> ConfirmMeaningAsync(string task,ImmutableDictionary<string,string> fields,bool assisted)
    {var s=await _repository.SnapshotAsync();Allowed(s);Require(task is SignTask or PropertyTask,"本地稿件未登记。");At(s,task==SignTask?"R5-O01.proposal":"R5-O02.claim");Source(s,task==SignTask?"SC-R5-SIGN":"SC-R5-LOST");var d=await _repository.GetDraftAsync(task)??throw new InvalidOperationException("正文未实际保存。");Require(!d.Deleted&&!string.IsNullOrWhiteSpace(d.Body),"保存正文与逐项意思核对分层，选项不能代空白稿。");string id=task==SignTask?SignId:PropertyId;return await Execute(Plan(s,id+":meaning:"+Guid.NewGuid(),"old_city_local_note_meaning_confirmed",new{task,assisted,free_english_understanding="not_claimed",language_score=(string?)null},[BranchOperations.Change(s,id+":meaning","optional_note_meaning",new SettlementNoteMeaning(d.Hash,assisted,fields))],draft:new(task,d.Id,d.Revision,d.Hash)));}
    private async ValueTask<DraftView> Note(string task,params (string Key,string Value)[] expected)
    {var s=await _repository.SnapshotAsync();var d=await _repository.GetDraftAsync(task)??throw new InvalidOperationException("正文未实际保存。");var m=Read<SettlementNoteMeaning>(s,(task==SignTask?SignId:PropertyId)+":meaning");Require(!d.Deleted&&!string.IsNullOrWhiteSpace(d.Body)&&m is not null&&m.DraftHash==d.Hash&&expected.All(e=>m.Fields.TryGetValue(e.Key,out var actual)&&actual==e.Value),"当前稿件意思、来源、归属或局部边界尚未逐项确认。");return d;}
    private static string EvidenceId(BranchSnapshot s,string action,string body)=>s.Receipts.Where(r=>r.ActionType==action&&r.ResultJson==body).OrderByDescending(r=>r.Sequence).FirstOrDefault()?.ReceiptId??throw new InvalidOperationException("当前实际来源回执缺失。");
    private SettlementPreview Preview(CommitPlanCommand c,string task,string hash){var token=Guid.NewGuid();_previews[token]=c;return new(token,true,[],task,hash);}
    public async ValueTask<SettlementPreview> PreviewSignHandoverAsync()
    {var s=await _repository.SnapshotAsync();Allowed(s);At(s,"R5-O01.keeper");var st=Sign(s);Require(st.Installed&&st.VisibleCheck==st.Configuration&&st.Consulted,"地方询议、实际同牌安装和当前可见字检查须完成。");Item(s,st.Board,st.Board==ReedBoard?"R5-LOCAL-SIGN-REED":"R5-LOCAL-SIGN-LANTERN","installed",Junction);var d=await Note(SignTask,("name",st.Main),("other",st.Other),("consultation","both_local_memories"),("maintainer",Crew),("scope","one_marker_no_history_change"));var result=new LocalSignResult(st.Instance,Contract.Fingerprint,st.Board,st.Main,st.Other,Crew,EvidenceId(s,"old_city_two_local_memories_consulted",BranchOperations.Entity(s,SignId+":consultation")!.Json),EvidenceId(s,"old_city_current_visible_sign_checked",BranchOperations.Entity(s,SignId+":check")!.Json),d.Hash,"one_local_marker_only",0,0,0);return Preview(Plan(s,SignId+":resolution","old_city_local_public_sign_received",result,[BranchOperations.Change(s,SignId,"optional_local_sign",st with{Completed=true}),BranchOperations.Change(s,SignId+":result","local_public_sign_result",result)],draft:new(SignTask,d.Id,d.Revision,d.Hash)),SignTask,d.Hash);}
    public ValueTask<CommandResult> ConfirmPreviewAsync(Guid token)=>_previews.TryGetValue(token,out var c)?Execute(c):ValueTask.FromResult(new CommandResult(CommitStatus.Rejected,null,[new("preview_closed",SignId,"本地预览已关闭，请重新核对。") ]));
    public void ClosePreview(Guid token)=>_previews.Remove(token);
    public ValueTask<string?> CurrentStreetSignLabelAsync()=>LabelCore();
    private async ValueTask<string?> LabelCore(){var s=await _repository.SnapshotAsync();return Read<LocalSignState>(s,SignId) is{Installed:true} st&&st.Fingerprint==Contract.Fingerprint?st.Main+" · "+st.Other:null;}
